ALTER TABLE public.vehicles ADD COLUMN service_states text[],ADD COLUMN operating_timezone text;
CREATE FUNCTION public.validate_vehicle_regional_context() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.service_states IS NOT NULL AND (cardinality(NEW.service_states)>51 OR EXISTS(SELECT 1 FROM unnest(NEW.service_states) s WHERE NOT public.us_state_catalog() ? s)) THEN RAISE EXCEPTION 'Select valid U.S. served states';END IF;IF NEW.operating_timezone IS NOT NULL AND NEW.operating_timezone<>'' AND NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.operating_timezone) THEN RAISE EXCEPTION 'Valid IANA timezone required';END IF;RETURN NEW;END $$;CREATE TRIGGER validate_vehicle_region BEFORE INSERT OR UPDATE OF service_states,operating_timezone ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.validate_vehicle_regional_context();